@import "@fontsource-variable/mona-sans";
@import "@fontsource-variable/geist-mono";

/* Faithful mode: warm linen page (#f9f7f4), charcoal text (#202020, 70% for secondary text),
   white cards, sand (#dcd2ba) hairlines and filled buttons that turn merlot (#3b1515) on
   hover. Ivory (#f3f1ea) is the card hover, camel (#c3b39c) the glow and faded heading tails,
   crimson (#8e1717) the sparing emphasis. */
:root {
  --background: oklch(0.9768 0.0045 78.3);
  --foreground: oklch(0.2435 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.2435 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.2435 0 0);
  --primary: oklch(0.255 0.0604 22.3);
  --primary-foreground: oklch(0.9768 0.0045 78.3);
  --secondary: oklch(0.8655 0.0341 88.1);
  --secondary-foreground: oklch(0.2435 0 0);
  --muted: oklch(0.9578 0.0095 93.6);
  --muted-foreground: oklch(0.2435 0 0 / 70%);
  --accent: oklch(0.9578 0.0095 93.6);
  --accent-foreground: oklch(0.2435 0 0);
  --destructive: oklch(0.4191 0.1538 27.1);
  --destructive-foreground: oklch(0.9768 0.0045 78.3);
  --border: oklch(0.8655 0.0341 88.1);
  --input: oklch(0.8655 0.0341 88.1);
  --ring: oklch(0.7741 0.0366 77);
  --highlight: oklch(0.4191 0.1538 27.1);
  --highlight-foreground: oklch(0.9768 0.0045 78.3);
  --glow: oklch(0.7741 0.0366 77);
  --chart-1: oklch(0.255 0.0604 22.3);
  --chart-2: oklch(0.7741 0.0366 77);
  --chart-3: oklch(0.4191 0.1538 27.1);
  --chart-4: oklch(0.3469 0.0242 248.5);
  --chart-5: oklch(0.8655 0.0341 88.1);
  --sidebar: oklch(0.9578 0.0095 93.6);
  --sidebar-foreground: oklch(0.2435 0 0);
  --sidebar-primary: oklch(0.255 0.0604 22.3);
  --sidebar-primary-foreground: oklch(0.9768 0.0045 78.3);
  --sidebar-accent: oklch(0.8655 0.0341 88.1);
  --sidebar-accent-foreground: oklch(0.2435 0 0);
  --sidebar-border: oklch(0.8655 0.0341 88.1);
  --sidebar-ring: oklch(0.7741 0.0366 77);

  --typeface-body: "Mona Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: var(--typeface-body);
  --typeface-mono: "Geist Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.1875rem;
  --page-width: 90rem;
  --page-gutter: clamp(1.25rem, 3.47vw, 3.125rem);
  --section-y: clamp(5.25rem, 9.72vw, 8.75rem);
}

/* The merlot world (the original's hero and phone header, and the dark sibling): merlot
   page, linen text, a slightly lifted merlot for cards, linen buttons with charcoal text,
   10% linen for quiet fills, 15% linen hairlines. */
.dark {
  --background: oklch(0.255 0.0604 22.3);
  --foreground: oklch(0.9768 0.0045 78.3);
  --card: oklch(0.2967 0.0585 22.8);
  --card-foreground: oklch(0.9768 0.0045 78.3);
  --popover: oklch(0.2967 0.0585 22.8);
  --popover-foreground: oklch(0.9768 0.0045 78.3);
  --primary: oklch(0.9768 0.0045 78.3);
  --primary-foreground: oklch(0.2435 0 0);
  --secondary: oklch(0.9768 0.0045 78.3 / 10%);
  --secondary-foreground: oklch(0.9768 0.0045 78.3);
  --muted: oklch(0.2967 0.0585 22.8);
  --muted-foreground: oklch(0.9768 0.0045 78.3 / 70%);
  --accent: oklch(0.2967 0.0585 22.8);
  --accent-foreground: oklch(0.9768 0.0045 78.3);
  --destructive: oklch(0.6482 0.1458 28.4);
  --destructive-foreground: oklch(0.2435 0 0);
  --border: oklch(0.9768 0.0045 78.3 / 15%);
  --input: oklch(0.9768 0.0045 78.3 / 15%);
  --ring: oklch(0.7741 0.0366 77);
  --highlight: oklch(0.6482 0.1458 28.4);
  --highlight-foreground: oklch(0.2435 0 0);
  --glow: oklch(0.7741 0.0366 77);
  --chart-1: oklch(0.9768 0.0045 78.3);
  --chart-2: oklch(0.7741 0.0366 77);
  --chart-3: oklch(0.6482 0.1458 28.4);
  --chart-4: oklch(0.8655 0.0341 88.1);
  --chart-5: oklch(0.9424 0.0298 85.6);
  --sidebar: oklch(0.2206 0.0495 22);
  --sidebar-foreground: oklch(0.9768 0.0045 78.3);
  --sidebar-primary: oklch(0.9768 0.0045 78.3);
  --sidebar-primary-foreground: oklch(0.2435 0 0);
  --sidebar-accent: oklch(0.2967 0.0585 22.8);
  --sidebar-accent-foreground: oklch(0.9768 0.0045 78.3);
  --sidebar-border: oklch(0.9768 0.0045 78.3 / 15%);
  --sidebar-ring: oklch(0.7741 0.0366 77);
}
